INSERT INTO gyms (id, name, location, description) VALUES ('g01', 'IronHub Fitness', '서울시 강남구', '최고급 장비와 전담 리프팅 플랫폼, 전문 코칭 스태프를 갖춘 프리미엄 스트렝스 트레이닝 센터입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g02', 'PulseZone Gym', '서울시 마포구', '최신 기능성 장비를 갖추고 유산소·HIIT 중심 프로그램을 운영하는 활기찬 피트니스 센터입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g03', 'CoreForge Studio', '서울시 용산구', '코어 트레이닝, 필라테스 기반 머신, 기능성 유연성 운동에 특화된 부티크 스튜디오입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g04', 'MaxLift Arena', '서울시 송파구', '풀 프리웨이트 구역과 대회 수준의 바벨을 갖춘 파워리프팅·보디빌딩 전문 대형 헬스장입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g05', 'FlexPoint Club', '서울시 서대문구', '다양한 머신과 클래스를 갖춰 모든 수준의 회원이 편리하게 이용할 수 있는 커뮤니티 헬스장입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g06', 'Apex Performance', '서울시 서초구', '스포츠 특화 컨디셔닝, 올림픽 리프팅, 크로스핏 트레이닝을 위한 애슬레틱 퍼포먼스 센터입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g07', 'Momentum Fitness', '서울시 노원구', '충분한 스트렝스 장비와 넓은 운동 공간, 합리적인 회원권을 제공하는 동네 밀착형 헬스장입니다.') ON CONFLICT (id) DO NOTHING;
INSERT INTO gyms (id, name, location, description) VALUES ('g08', 'UrbanSweat Gym', '서울시 종로구', '유산소, 스트렝스, 회복 시설을 한 공간에 갖춘 현대적인 멀티 퍼포즈 헬스장입니다.') ON CONFLICT (id) DO NOTHING;
